import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * No `separator` part, by decision (spec D-BC-2): the chevron between crumbs is
 * drawn by the sheet as a `::before` on adjacency — invisible to the
 * accessibility tree, automatic, RTL-flipped — never markup and never a text
 * glyph. A consumer who wants another separator overrides the pseudo-element in
 * their own layer; every selector here is `:where()`, so the override costs no
 * specificity fight.
 */
export type BreadcrumbPart = "root" | "list" | "item" | "link" | "ellipsis" | "ellipsisTrigger";

export const anatomy: Anatomy<BreadcrumbPart> = createAnatomy("breadcrumb").parts(
  "root",
  "list",
  "item",
  "link",
  "ellipsis",
  "ellipsisTrigger",
);

export const parts: Record<BreadcrumbPart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server.
 *
 * The keyboard is entirely native (APG Breadcrumb defines no keys of its own):
 * Tab traverses links and the ellipsis button in document order, `hidden` items
 * are out of the tab order for free, Enter navigates the link, Enter/Space
 * activate the real `<button>` — whose native `click` also covers assistive
 * technologies, which is why there is no `interaction/press` here. No roving
 * tabindex, no arrow keys: adding them would diverge from the pattern.
 *
 * `list` carries a permanent `tabindex="-1"`: it is the focus target of a
 * pointer/touch reveal (D-BC-4) — never in the Tab order, never styled with a
 * ring, so the focus is not lost and no ring appears under a mouse.
 */

import { boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./breadcrumb.anatomy";
import { getEllipsisTriggerId, getListId, getRootId } from "./breadcrumb.dom";
import type {
  BreadcrumbApi,
  BreadcrumbItemProps,
  BreadcrumbLinkProps,
  BreadcrumbSchema,
} from "./breadcrumb.types";

export function connect<T extends PropTypes>(
  service: Service<BreadcrumbSchema>,
  normalize: NormalizeProps<T>,
): BreadcrumbApi<T> {
  const { context, prop, send, scope } = service;

  const expanded = context.get("expanded");
  const state = expanded ? "expanded" : "collapsed";

  return {
    expanded,

    setExpanded(next: boolean): void {
      // Never `ELLIPSIS.CLICK`: the programmatic path moves no focus.
      send({ type: "EXPANDED.SET", expanded: next });
    },

    expand(): void {
      send({ type: "EXPANDED.SET", expanded: true });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        // The landmark's name. Two breadcrumbs on a page need two labels.
        "aria-label": prop("label"),
        "data-state": state,
      }),

    getListProps: (): T["element"] =>
      normalize.element({
        ...parts.list.attrs,
        id: getListId(scope),
        dir: prop("dir"),
        tabIndex: -1,
        "data-state": state,
      }),

    getItemProps: (itemProps?: BreadcrumbItemProps): T["element"] => {
      const collapsed = itemProps?.collapsed === true;
      return normalize.element({
        ...parts.item.attrs,
        // `hidden` removes the level from layout AND from the accessibility
        // tree while the trail is collapsed. `data-collapsed` stays posted once
        // revealed — the reveal fade and the re-collapse rescue key on it.
        hidden: collapsed && !expanded ? true : undefined,
        "data-collapsed": dataAttr(collapsed),
        // Only the items that take part in the disclosure wear the state; an
        // attribute on every crumb would describe nothing.
        "data-state": collapsed ? state : undefined,
      });
    },

    getLinkProps: (linkProps?: BreadcrumbLinkProps): T["element"] => {
      const current = linkProps?.current === true;
      return normalize.element({
        ...parts.link.attrs,
        // `"page"` and no other value — and `aria-current` is a global
        // attribute, valid on the `span` a consumer substitutes for the
        // current level.
        "aria-current": current ? "page" : undefined,
        "data-current": dataAttr(current),
      });
    },

    getEllipsisProps: (): T["element"] =>
      normalize.element({
        ...parts.ellipsis.attrs,
        // A real list item: it participates in the sheet's chevron adjacency,
        // and it leaves layout and the accessibility tree once revealed.
        hidden: expanded ? true : undefined,
        "data-state": state,
      }),

    getEllipsisTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.ellipsisTrigger.attrs,
        id: getEllipsisTriggerId(scope),
        type: "button",
        "aria-expanded": boolAttr(expanded),
        "aria-controls": getListId(scope),
        // The glyph is the sheet's three dots, never text — so the name has to
        // come from somewhere, and it is this label.
        "aria-label": prop("ellipsisLabel"),
        "data-state": state,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "ELLIPSIS.CLICK" });
        },
      }),
  };
}

import { contains, query, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "breadcrumb";

/**
 * Written out rather than read from `parts`: the anatomy builds the same
 * strings, and a component that imports its own anatomy into its DOM helpers
 * pays for the builder in every bundle that only wanted a query — the `tabs`
 * decision, kept.
 */
const LIST_SELECTOR = '[data-part~="breadcrumb:list"]';
const COLLAPSED_ITEM_SELECTOR = '[data-part~="breadcrumb:item"][data-collapsed]';
const LINK_SELECTOR = '[data-part~="breadcrumb:link"]';

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getListId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "list");
}

export function getEllipsisTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "ellipsis-trigger");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getListEl(scope: Scope): HTMLElement | null {
  return scope.getById(getListId(scope));
}

export function getEllipsisTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getEllipsisTriggerId(scope));
}

/**
 * The first link inside a collapsed item of *this* list, in DOM order — where
 * the focus lands after a keyboard or gamepad reveal. Filtered to this list the
 * way `tabs` filters its triggers: a breadcrumb nested in another component's
 * markup is an ordinary shape, and `querySelectorAll` from the list would
 * otherwise hand back a stranger's crumbs.
 */
export function getFirstCollapsedLinkEl(scope: Scope): HTMLElement | null {
  const list = getListEl(scope);
  if (list === null) return null;
  for (const item of queryAll<HTMLElement>(list, COLLAPSED_ITEM_SELECTOR)) {
    if (item.closest(LIST_SELECTOR) !== list) continue;
    const link = query<HTMLElement>(item, LINK_SELECTOR);
    if (link !== null) return link;
  }
  return null;
}

/**
 * Whether the focus currently sits inside a collapsed item of this list — read
 * *before* the render that hides it, because after that render the browser has
 * already ejected the focus to `body` and the fact is unrecoverable.
 */
export function isActiveElementInCollapsedRun(scope: Scope): boolean {
  const list = getListEl(scope);
  const active = scope.getActiveElement();
  if (list === null || active === null) return false;
  const item = active.closest(COLLAPSED_ITEM_SELECTOR);
  return item !== null && contains(list, item);
}

/**
 * The breadcrumb machine is the APG Disclosure pattern folded inside the APG
 * Breadcrumb pattern (spec D-BC-1): intermediate levels marked `collapsed` are
 * `hidden`, one ellipsis button reveals them **in place** — the `nav > ol > li`
 * structure and the reading order never change, and no `menu` semantics are
 * introduced for site navigation. The overflow-menu presentation is a
 * composition (`EllipsisTrigger render={<Menu.Trigger/>}`), never a dependency:
 * `menu` is the 8 kB overlay-and-collection class, and embedding it here would
 * bill a menu to everyone who only wanted a trail of links.
 *
 * One state, and the data lives in context — the toggle doctrine: states model
 * interaction modes, never data. What earns this component a machine at all
 * (against the `separator` bar) is the bindable, the derived `aria-controls`
 * pair, and one genuinely stateful move: the ellipsis button disappears under
 * the very focus that activated it, and the focus has to be walked somewhere on
 * purpose (D-BC-4/D-BC-5).
 *
 * The focus move is played by the `watch` on `expanded`, which relies on the
 * hard rule that an adapter updates the DOM *before* running its watchers:
 * `hidden` is already off the revealed items when the action goes looking for
 * the first link. Where the focus goes depends on the modality *at the moment of
 * activation*: keyboard/gamepad land on the first revealed link (a legitimate
 * ring), pointer/touch land on the list (`tabindex="-1"`, no ring styled) — a
 * programmatic `focus()` matches `:focus-visible` on all three engines, so
 * focusing the link on a click would paint a ring nobody asked for.
 */

import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import {
  focusElement,
  getInputModality,
  isFocusVisibleModality,
  trackInputModality,
} from "../../nav";
import {
  getEllipsisTriggerEl,
  getFirstCollapsedLinkEl,
  getListEl,
  isActiveElementInCollapsedRun,
} from "./breadcrumb.dom";
import type { BreadcrumbSchema } from "./breadcrumb.types";

export const machine: Machine<BreadcrumbSchema> = createMachine<BreadcrumbSchema>({
  props({ props }) {
    return { label: "Breadcrumb", ellipsisLabel: "Show hidden items", ...props };
  },

  context({ prop, bindable }) {
    return {
      expanded: bindable<boolean>(() => ({
        defaultValue: prop("defaultExpanded") ?? false,
        value: prop("expanded"),
        onChange: (expanded) => prop("onExpandedChange")?.({ expanded }),
        debugLabel: "breadcrumb expanded",
      })),
    };
  },

  refs() {
    return { pendingFocus: null };
  },

  // Pure — SSR renders the same markup the first client render agrees with.
  initialState() {
    return "idle";
  },

  // Like toggle: the tracker has to be running before the first event, or the
  // modality read at the moment of the reveal would be a stale default.
  effects: ["trackModality"],

  // Played post-render by the adapter (the DOM-before-watch hard rule), so
  // `hidden` is already applied/removed when the action resolves its elements.
  watch({ context, track, action }) {
    track(
      () => [context.get("expanded")],
      () => action(["focusAfterExpandedChange"]),
    );
  },

  on: {
    // Guarded: a second activation while already expanded is a no-op, not a
    // second emission.
    "ELLIPSIS.CLICK": { guard: "!isExpanded", actions: ["markPendingReveal", "expand"] },
    "EXPANDED.SET": { actions: ["setExpanded"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isExpanded: ({ context }) => context.get("expanded"),
    },

    actions: {
      expand({ context }) {
        context.set("expanded", true);
      },

      markPendingReveal({ refs }) {
        refs.set("pendingFocus", "reveal");
      },

      setExpanded({ context, event, refs, scope }) {
        if (event.type !== "EXPANDED.SET") return;
        // Read synchronously BEFORE the render: after it, the browser has
        // already ejected the focus of a hidden item to `body`, and "it was
        // ours" is unrecoverable (D-BC-5).
        if (!event.expanded && context.get("expanded") && isActiveElementInCollapsedRun(scope)) {
          refs.set("pendingFocus", "rescue");
        }
        context.set("expanded", event.expanded);
      },

      focusAfterExpandedChange({ refs, scope }) {
        const pending = refs.get("pendingFocus");
        // A programmatic change owes nobody a focus move — steal nothing.
        if (pending === null) return;
        refs.set("pendingFocus", null);
        const list = getListEl(scope);
        const target =
          pending === "reveal"
            ? isFocusVisibleModality(getInputModality(scope.getDoc()))
              ? (getFirstCollapsedLinkEl(scope) ?? list)
              : list
            : (getEllipsisTriggerEl(scope) ?? list);
        focusElement(target);
      },
    },

    effects: {
      // No listener: the modality is read once, at the moment of the reveal.
      // Holding the handle is the whole job.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction } from "../../types";

export interface BreadcrumbExpandedChangeDetails {
  readonly expanded: boolean;
}

export interface BreadcrumbMachineProps {
  readonly dir?: Direction | undefined;
  /**
   * Accessible name of the `nav` landmark. Defaults to `"Breadcrumb"` — the
   * consumer localises it, and two breadcrumbs on one page MUST carry two
   * different labels or the landmarks are indistinguishable.
   */
  readonly label?: string | undefined;
  /** Accessible name of the ellipsis button. Defaults to `"Show hidden items"`. */
  readonly ellipsisLabel?: string | undefined;
  /** Controlled: present means the consumer owns the value. */
  readonly expanded?: boolean | undefined;
  readonly defaultExpanded?: boolean | undefined;
  readonly onExpandedChange?: ((details: BreadcrumbExpandedChangeDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedBreadcrumbMachineProps extends BreadcrumbMachineProps {
  readonly label: string;
  readonly ellipsisLabel: string;
}

export interface BreadcrumbItemProps {
  /**
   * An intermediate level hidden behind the ellipsis. `hidden` while the trail
   * is collapsed — removed from layout AND from the accessibility tree — and
   * `data-collapsed` stays posted once revealed, which is what the reveal fade
   * and the re-collapse rescue both key on.
   */
  readonly collapsed?: boolean | undefined;
}

export interface BreadcrumbLinkProps {
  /**
   * The current page. `aria-current="page"` is a global attribute, so the level
   * may be rendered as a `span` through `render` and stay valid.
   */
  readonly current?: boolean | undefined;
}

export interface BreadcrumbSchema extends MachineSchema {
  state: "idle";
  props: ResolvedBreadcrumbMachineProps;
  /** Bindable, primitive — no `isEqual` needed. */
  context: { expanded: boolean };
  /**
   * Where the focus is owed after the next render, or `null` when nobody moved
   * it. `"reveal"` is posted only by `ELLIPSIS.CLICK` — a programmatic
   * `EXPANDED.SET` never steals the focus — and `"rescue"` only by a collapse
   * that is about to hide the element holding it.
   */
  refs: { pendingFocus: "reveal" | "rescue" | null };
  event: { type: "ELLIPSIS.CLICK" } | { type: "EXPANDED.SET"; expanded: boolean };
  action: "expand" | "markPendingReveal" | "setExpanded" | "focusAfterExpandedChange";
  guard: "isExpanded";
  effect: "trackModality";
}

export interface BreadcrumbApi<T extends PropTypes = PropTypes> {
  readonly expanded: boolean;
  /** Programmatic — never moves the focus, unlike an ellipsis activation. */
  setExpanded(expanded: boolean): void;
  /** Sugar for `setExpanded(true)`. */
  expand(): void;
  getRootProps(): T["element"];
  getListProps(): T["element"];
  getItemProps(props?: BreadcrumbItemProps): T["element"];
  getLinkProps(props?: BreadcrumbLinkProps): T["element"];
  getEllipsisProps(): T["element"];
  getEllipsisTriggerProps(): T["button"];
}

export { anatomy, type BreadcrumbPart, parts } from "./breadcrumb.anatomy";
export { connect } from "./breadcrumb.connect";
export {
  getEllipsisTriggerEl,
  getEllipsisTriggerId,
  getFirstCollapsedLinkEl,
  getListEl,
  getListId,
  getRootEl,
  getRootId,
  isActiveElementInCollapsedRun,
} from "./breadcrumb.dom";
export { machine } from "./breadcrumb.machine";
export type {
  BreadcrumbApi,
  BreadcrumbExpandedChangeDetails,
  BreadcrumbItemProps,
  BreadcrumbLinkProps,
  BreadcrumbMachineProps,
  BreadcrumbSchema,
  ResolvedBreadcrumbMachineProps,
} from "./breadcrumb.types";

/**
 * Breadcrumb in React: one machine in the root and six thin parts.
 *
 * There is no presence and no portal here, and that is the design rather than an
 * omission. A folded level leaves through the `hidden` attribute, which is
 * instantaneous by construction — nothing to animate on the way out, so nothing
 * to hold mounted. The reveal is a fade the sheet owns.
 *
 * The one thing this adapter does that the core cannot is **order**: `useMachine`
 * runs the machine's watchers in a layout effect, i.e. after the commit that took
 * `hidden` off the revealed levels. That is what lets the focus move land on a
 * level that is really in the tree — the whole reason this component has a
 * machine (see the head of `breadcrumb.machine.ts`).
 *
 * `EllipsisTrigger` is also the composition point for the overflow-menu
 * presentation: `<BreadcrumbEllipsisTrigger render={<MenuTrigger />} />` gives one
 * element both identities, and the two sheets match it at once. The menu is never
 * a dependency of this component — it is the 8 kB overlay-and-collection class,
 * and a trail of links must not pay for one.
 */

import * as breadcrumb from "@standarui/core/breadcrumb";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type BreadcrumbApi = breadcrumb.BreadcrumbApi<ReactPropTypes>;

export interface UseBreadcrumbProps
  extends breadcrumb.BreadcrumbMachineProps,
    MachineRuntimeProps {}

const BreadcrumbPartContext = createPartContext<BreadcrumbApi>("Breadcrumb");

export function useBreadcrumb(props: UseBreadcrumbProps): BreadcrumbApi {
  return breadcrumb.connect(useMachine(breadcrumb.machine, props), normalizeProps);
}

/** The api of the trail a subtree sits in — a consumer's own chrome reads it. */
export function useBreadcrumbContext(): BreadcrumbApi {
  return BreadcrumbPartContext.usePart("BreadcrumbContext");
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "label",
  "ellipsisLabel",
  "expanded",
  "defaultExpanded",
  "onExpandedChange",
] as const;

export interface BreadcrumbRootProps
  extends UseBreadcrumbProps,
    PartProps<"nav", UseBreadcrumbProps> {}

/**
 * A `nav` landmark, named by `label`. Two trails on one page need two names, or
 * the two landmarks are indistinguishable to anyone navigating by them.
 */
export function BreadcrumbRoot(props: BreadcrumbRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useBreadcrumb(machineProps);

  return (
    <BreadcrumbPartContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "nav",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </BreadcrumbPartContext.Provider>
  );
}

/**
 * An `ol`, and it holds nothing but `Item`s and the `Ellipsis`: `ol > li` is the
 * structure a screen reader counts the levels from, and a stray `div` between the
 * two breaks the count. It carries a permanent `tabindex="-1"` — never in the Tab
 * order, it is where a pointer reveal parks the focus.
 */
export const BreadcrumbList: (props: PartProps<"ol">) => ReactNode = createPart<
  BreadcrumbApi,
  "ol"
>(BreadcrumbPartContext, {
  name: "BreadcrumbList",
  element: "ol",
  props: (api) => api.getListProps(),
});

export interface BreadcrumbItemProps
  extends breadcrumb.BreadcrumbItemProps,
    PartProps<"li", breadcrumb.BreadcrumbItemProps> {}

/**
 * One level. `collapsed` marks it as living behind the ellipsis: it is `hidden`
 * while the trail is folded — out of layout and out of the accessibility tree —
 * and keeps `data-collapsed` once revealed, which is what the fade keys on.
 */
export function BreadcrumbItem(props: BreadcrumbItemProps): ReactNode {
  const [itemProps, rest] = splitProps(props, ["collapsed"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = BreadcrumbPartContext.usePart("BreadcrumbItem");

  return useRender({
    render,
    asChild,
    element: "li",
    props: api.getItemProps(itemProps),
    elementProps,
    children,
  });
}

export interface BreadcrumbLinkProps
  extends breadcrumb.BreadcrumbLinkProps,
    PartProps<"a", breadcrumb.BreadcrumbLinkProps> {}

/**
 * An `a[href]` by default. The current level is usually rendered as a `span`
 * through `render` — `aria-current` is a global attribute, so it stays valid
 * there — and a router's own `Link` drops in the same way.
 */
export function BreadcrumbLink(props: BreadcrumbLinkProps): ReactNode {
  const [linkProps, rest] = splitProps(props, ["current"]);
  const { render, asChild, children, ...elementProps } = rest;
  const api = BreadcrumbPartContext.usePart("BreadcrumbLink");

  return useRender({
    render,
    asChild,
    element: "a",
    props: api.getLinkProps(linkProps),
    elementProps,
    children,
  });
}

/**
 * The `li` that hosts the ellipsis button — a real list item, so the sheet's
 * chevrons count it by adjacency like any other level. It leaves with the reveal.
 */
export const BreadcrumbEllipsis: (props: PartProps<"li">) => ReactNode = createPart<
  BreadcrumbApi,
  "li"
>(BreadcrumbPartContext, {
  name: "BreadcrumbEllipsis",
  element: "li",
  props: (api) => api.getEllipsisProps(),
});

/**
 * The disclosure button. It renders no children of its own: the three dots are
 * the sheet's, never a text `…` — a glyph's ink rests on its baseline rather than
 * in the middle of its box — and the accessible name comes from `ellipsisLabel`.
 */
export const BreadcrumbEllipsisTrigger: (props: PartProps<"button">) => ReactNode = createPart<
  BreadcrumbApi,
  "button"
>(BreadcrumbPartContext, {
  name: "BreadcrumbEllipsisTrigger",
  element: "button",
  props: (api) => api.getEllipsisTriggerProps(),
});

/**
 * `<Breadcrumb items={…}/>` — one loop, and two things the layer derives rather
 * than asks for.
 *
 * **The last entry is the current one**, and that is the trail's definition and
 * not a convenience. APG marks the page you are on with `aria-current="page"`, and
 * a trail whose final level still linked somewhere would be a link to the document
 * already open. So the last entry drops its `href` and renders through `<span>` —
 * which stays valid, `aria-current` being a global attribute — exactly as the
 * parts form on the documentation site already wrote by hand. An entry cannot
 * override it: "which level am I on" is positional information, and a second
 * spelling of it would be a way to publish a trail with two current levels or
 * none.
 *
 * **The ellipsis is placed, not listed.** `collapsed` marks the levels that live
 * behind the fold; the button that reveals them belongs immediately before the
 * first of them, and nowhere else. Asking a consumer to interleave it in `items`
 * would let them put it after the fold, or twice, and the machine has no way to
 * refuse either. So the layer finds the first collapsed entry and emits the
 * `Ellipsis` there. A trail with no collapsed entry gets no ellipsis at all, which
 * is what `findIndex` returning `-1` already means.
 *
 * **`flatMap` rather than a fragment around the pair**, for the reason `tabs`
 * gives: `BreadcrumbList` renders an `ol` and screen readers count levels off
 * `ol > li`. A fragment renders no node and would pass the parity comparison, but
 * writing the ellipsis and the item as a unit in the source says they are one
 * level, and they are two.
 */

import type {
  BreadcrumbItemProps as CoreBreadcrumbItemProps,
  BreadcrumbLinkProps as CoreBreadcrumbLinkProps,
} from "@standarui/core/breadcrumb";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  BreadcrumbEllipsis,
  BreadcrumbEllipsisTrigger,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbRoot,
  type UseBreadcrumbProps,
} from "./breadcrumb";

/**
 * The current level renders through this rather than as an anchor. Hoisted to the
 * module so the element is allocated once for every trail on the page — `useRender`
 * clones it, so sharing one is safe.
 */
const CURRENT = <span />;

/** One level of the trail. */
export interface BreadcrumbEntry {
  readonly label: ReactNode;
  /** Where this level points. Ignored on the last entry — see above. */
  readonly href?: string | undefined;
  /** Behind the fold. The reveal button is placed before the first of these. */
  readonly collapsed?: boolean | undefined;
}

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 */
export interface BreadcrumbParts {
  readonly list?: PartProps<"ol"> | undefined;
  readonly ellipsis?: PartProps<"li"> | undefined;
  readonly ellipsisTrigger?: PartProps<"button"> | undefined;
  /**
   * Applied to EVERY level, hence no `collapsed` — the entry's own field, already
   * excluded through `Own` — and no `id` **or IDREF**: one id repeated down a list
   * is a broken reference per level, and one `aria-labelledby` repeated gives every
   * level the same name, which no dangling-IDREF check can see because the id it
   * points at does resolve. `ref` goes because a single ref held by N items ends up
   * holding the last one.
   */
  readonly item?:
    | Omit<
        PartProps<"li", CoreBreadcrumbItemProps>,
        "id" | "ref" | "aria-labelledby" | "aria-describedby"
      >
    | undefined;
  /**
   * Applied to EVERY link, and excluded for the same reasons — plus `href` and
   * `current`, which are the two the layer derives. A fixed `href` here would point
   * every level at one place, and a fixed `current` would publish a trail with as
   * many current levels as it has entries.
   */
  readonly link?:
    | Omit<
        PartProps<"a", CoreBreadcrumbLinkProps>,
        "id" | "ref" | "href" | "current" | "aria-labelledby" | "aria-describedby"
      >
    | undefined;
}

export interface BreadcrumbComposedProps
  extends UseBreadcrumbProps,
    Omit<PartProps<"nav", UseBreadcrumbProps>, "children"> {
  readonly items: readonly BreadcrumbEntry[];
  readonly parts?: BreadcrumbParts | undefined;
}

export function Breadcrumb(props: BreadcrumbComposedProps): ReactNode {
  const { items, parts, ...root } = props;
  const fold = items.findIndex((item) => item.collapsed === true);
  const last = items.length - 1;

  // Extracted rather than written inline. `href` is the natural key and the usual
  // one, but a level is allowed to have none — the current one never does — so the
  // position is the fallback, which is safe for the reason `menu/composed.tsx`
  // gives for its separators: a trail is ordered and does not reorder, and no
  // level holds focus or state that a re-key could move.
  const renderLevel = (item: BreadcrumbEntry, index: number): readonly ReactNode[] => [
    index === fold ? (
      <BreadcrumbEllipsis key="fold" {...parts?.ellipsis}>
        <BreadcrumbEllipsisTrigger {...parts?.ellipsisTrigger} />
      </BreadcrumbEllipsis>
    ) : null,
    <BreadcrumbItem key={item.href ?? `level:${index}`} collapsed={item.collapsed} {...parts?.item}>
      <BreadcrumbLink
        href={index === last ? undefined : item.href}
        current={index === last}
        render={index === last ? CURRENT : undefined}
        {...parts?.link}
      >
        {item.label}
      </BreadcrumbLink>
    </BreadcrumbItem>,
  ];

  return (
    <BreadcrumbRoot {...root}>
      <BreadcrumbList {...parts?.list}>{items.flatMap(renderLevel)}</BreadcrumbList>
    </BreadcrumbRoot>
  );
}

